//! End-to-end tests of the mchime binary.
//!
//! Expected outputs are vsearch's `--nonchimeras`, `--chimeras`,
//! `--tabbedout` and `--alnout` of `--chimeras_denovo` (with
//! `--notrunclabels --qmask soft --minseqlength 0 --fasta_width 0`) on
//! input sorted by decreasing abundance (`sortby --size`). `--parts` is
//! `--chimeras_parts`, `--max-parents` `--chimeras_parents_max`,
//! `--min-segment` `--chimeras_length_min`, `--diff-pct`
//! `--chimeras_diff_pct`, `--table` `--tabbedout`, `--alignments`
//! `--alnout` and `--width` `--alignwidth`.

use std::path::PathBuf;
use std::process::{Command, Output, Stdio};

/// Chimeras of two to four of seven parents of 500 bases (two of them a
/// few substitutions from another), some with a substitution or lower
/// case, variants of the parents, a random sequence, a short and an empty
/// one, sorted by decreasing abundance.
const INPUT: &str = r##">p6;size=900

>p0;size=700

>p1;size=700

>p2;size=500

>p3;size=400

>p4;size=300

>p5;size=300

>m0;size=100

>m14;size=100

>m4;size=100

>m7;size=100

>v0;size=50

>v1;size=50

>v2;size=50

>v3;size=50

>m15;size=20

>s;size=8
G
>m11;size=5

>m5;size=5

>m6;size=5

>x;size=3

>e;size=2

>m13;size=2

>m1;size=2

>m8;size=2

>m10;size=1

>m12;size=1

>m2;size=1

>m3;size=1

>m9;size=1

"##;

/// A path in the temporary directory, unique to this test process.
fn temp_path(name: &str) -> PathBuf {
    std::env::temp_dir().join(format!("rsearch-mchime-{}-{name}", std::process::id()))
}

/// What mchime wrote: the non-chimeras, chimeras, table and alignments.
#[derive(Debug, PartialEq)]
struct Written([String; 4]);

/// Runs mchime with `args` on `input`, writing every output.
fn run(name: &str, args: &[&str], input: &str) -> (Output, Written) {
    let inp = temp_path(&format!("{name}-in"));
    std::fs::write(&inp, input).unwrap();
    let outs = ["chimeras", "table", "alignments"].map(|o| temp_path(&format!("{name}-{o}")));
    let mut command = Command::new(env!("CARGO_BIN_EXE_mchime"));
    command.arg("-i").arg(&inp);
    for (option, path) in ["--chimeras", "--table", "--alignments"].iter().zip(&outs) {
        command.arg(option).arg(path);
    }
    let output = command.args(args).stdin(Stdio::null()).output().unwrap();
    let read = |p: &PathBuf| std::fs::read_to_string(p).unwrap_or_default();
    let written = Written([
        String::from_utf8_lossy(&output.stdout).into_owned(),
        read(&outs[0]),
        read(&outs[1]),
        read(&outs[2]),
    ]);
    for p in outs.iter().chain([&inp]) {
        let _ = std::fs::remove_file(p);
    }
    (output, written)
}

/// Runs mchime, which must succeed, and returns what it wrote.
fn mchime(name: &str, args: &[&str], input: &str) -> Written {
    let (output, written) = run(name, args, input);
    assert!(
        output.status.success(),
        "mchime failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    written
}

