#[test]
fn finds_nothing_in_nothing() {
    assert_eq!(mchime("empty", &[], ""), Written(Default::default()));
}

#[test]
fn rejects_invalid_arguments() {
    for args in [
        &["--parts", "1"][..],
        &["--parts", "101"],
        &["--max-parents", "1"],
        &["--max-parents", "21"],
        &["--min-segment", "0"],
        &["--diff-pct", "51"],
        &["--diff-pct", "-1"],
        &["--abskew", "0.5"],
    ] {
        assert_eq!(
            run("args", args, INPUT).0.status.code(),
            Some(2),
            "{args:?}"
        );
    }
    let (output, _) = run("bad", &[], ">a;size=0\nACGT\n");
    assert_eq!(output.status.code(), Some(1));
}
